def count_distinct_characters(string: str) -> int:
    """ Given a string, calculate the count of distinct characters (ignoring case) present within it.
    >>> count_distinct_characters('xyzXYZ')
    3
    >>> count_distinct_characters('Jerry')
    4
    """
    string = string.lower()
    distinct_chars = set()

    for char in string:
        if char.isalpha():
            distinct_chars.add(char)

    return len(distinct_chars)
